"""
Uniform Sum Problem
Implement solution to determine if we can make sums equal under given operations.
"""
import sys

def solve():
    N = int(sys.stdin.readline().strip())
    A = list(map(int, sys.stdin.readline().split()))
    B = list(map(int, sys.stdin.readline().split()))

    freqA = {}
    freqB = {}
    a_m = 0
    b_m = 0
    for v in A:
        if v == -1:
            a_m += 1
        else:
            freqA[v] = freqA.get(v, 0) + 1
    for v in B:
        if v == -1:
            b_m += 1
        else:
            freqB[v] = freqB.get(v, 0) + 1
    lenA_known = sum(freqA.values())
    lenB_known = sum(freqB.values())
    max_known = 0
    if freqA or freqB:
        max_known = max(max(freqA.keys(), default=0), max(freqB.keys(), default=0))
    # Quick check if many -1 can pair with all knowns
    if b_m >= lenA_known and a_m >= lenB_known:
        print("Yes")
        return
    Sset = set()
    for a in freqA:
        for b in freqB:
            Sset.add(a + b)
    possible = False
    for S in Sset:
        if S < max_known:
            continue
        matched = 0
        for a, ca in freqA.items():
            b = S - a
            cb = freqB.get(b, 0)
            matched += min(ca, cb)
        unmatchedA = lenA_known - matched
        unmatchedB = lenB_known - matched
        if unmatchedA <= b_m and unmatchedB <= a_m:
            possible = True
            break
    print("Yes" if possible else "No")

if __name__ == "__main__":
    solve()

