    n=len(caption)
    pref=[[0]*(n+1) for _ in range(26)]
    for c in range(26):
        for i,ch in enumerate(caption,1):
            pref[c][i]=pref[c][i-1]+abs(ord(ch)-97-c)
    INF=10**18
    dp=[INF]*(n+1)
    dp[0]=0
    best=[INF]*26
    bestpos=[-1]*26
    for i in range(1,n+1):
        j=i-3
        if j>=0:
            for c in range(26):
                val=dp[j]-pref[c][j]
                if val<best[c]:
                    best[c]=val
                    bestpos[c]=j
        mincost=INF
        for c in range(26):
            cost=pref[c][i]+best[c]
            if cost<mincost:
                mincost=cost
        dp[i]=mincost
    return dp[n]
