from typing import List

class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0]*n
    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x
    def union(self, x: int, y: int) -> None:
        rx = self.find(x)
        ry = self.find(y)
        if rx == ry:
            return
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Filter numbers > threshold, they are isolated
        large_count = 0
        small_nums = []
        for v in nums:
            if v <= threshold:
                small_nums.append(v)
            else:
                large_count += 1
        # Map value to index
        idx_map = {v: i for i, v in enumerate(small_nums)}
        dsu = DSU(len(small_nums))
        n = len(small_nums)
        first = [-1]*(threshold+1)
        for val in small_nums:
            idx = idx_map[val]
            for m in range(val, threshold+1, val):
                if first[m] == -1:
                    first[m] = idx
                else:
                    dsu.union(idx, first[m])
        # Count distinct components among small numbers
        roots = set()
        for i in range(n):
            roots.add(dsu.find(i))
        return len(roots) + large_count

