def greedy_permutation(s, L):
    flips=0
    n=len(s)
    i=0
    while i<n:
        j=i
        while j<n and s[j]==s[i]:
            j+=1
        run=j-i
        flips+=run//(L+1)
        i=j
    return flips


def dp_flips(s, L):
    n=len(s)
