class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n <= 1:
            return 1

        def flips_needed(max_len: int) -> int:
            INF = 10 ** 9
            dp_prev0 = [INF] * (max_len + 1)
            dp_prev1 = [INF] * (max_len + 1)
            first_bit = ord(s[0]) - 48
            dp_prev0[1] = 0 if first_bit == 0 else 1
            dp_prev1[1] = 0 if first_bit == 1 else 1
            for i in range(1, n):
                bit = ord(s[i]) - 48
                dp_cur0 = [INF] * (max_len + 1)
                dp_cur1 = [INF] * (max_len + 1)
                for l in range(1, max_len + 1):
                    prevcost = dp_prev0[l]
                    if prevcost != INF:
                        if l < max_len:
                            newl = l + 1
                            cost = prevcost + (0 if bit == 0 else 1)
                            if cost < dp_cur0[newl]:
                                dp_cur0[newl] = cost
                        cost = prevcost + (0 if bit == 1 else 1)
                        if cost < dp_cur1[1]:
                            dp_cur1[1] = cost
                    prevcost = dp_prev1[l]
                    if prevcost != INF:
                        if l < max_len:
                            newl = l + 1
                            cost = prevcost + (0 if bit == 1 else 1)
                            if cost < dp_cur1[newl]:
                                dp_cur1[newl] = cost
                        cost = prevcost + (0 if bit == 0 else 1)
                        if cost < dp_cur0[1]:
                            dp_cur0[1] = cost
                dp_prev0, dp_prev1 = dp_cur0, dp_cur1
            best = INF
            for l in range(1, max_len + 1):
                if dp_prev0[l] < best:
                    best = dp_prev0[l]
                if dp_prev1[l] < best:
                    best = dp_prev1[l]
            return best

        low, high = 1, n
        while low < high:
            mid = (low + high) // 2
            needed = flips_needed(mid)
            if needed <= numOps:
                high = mid
            else:
                low = mid + 1
        return low

