def solve(N,K,X,T):
    prefix=[0]
    for t in T:
        prefix.append(prefix[-1]+t)
    # dp[i] dict day->mincost
    dp=[{} for _ in range(N+1)]
    INF_NEG=-10**18
    dp[0][INF_NEG]=0
    for i in range(1,N+1):
        for j in range(i-1, max(-1,i-K-1), -1):
            maxT=max(T[j:i]) if j>=0 else -10**18
            Tsum=prefix[i]-prefix[j]
            # iterate previous day states
            for prev_day, cost_prev in dp[j].items():
                d_new = max(maxT, prev_day + X)
                cost_added = (i-j)*d_new - Tsum
                new_cost=cost_prev + cost_added
                if d_new in dp[i]:
                    if new_cost < dp[i][d_new]:
                        dp[i][d_new]=new_cost
                else:
                    dp[i][d_new]=new_cost
    return min(dp[N].values())

