import itertools, math

def brute(N,p,A):
    zeros=[(i,j) for i in range(N) for j in range(N) if A[i][j]==0]
    K=len(zeros)
    total=[[0]*N for _ in range(N)]
    for vals in itertools.product(range(1,p), repeat=K):
        B=[row[:] for row in A]
        for (i,j),v in zip(zeros,vals):
            B[i][j]=v
        # compute B^p
        res=[[1 if i==j else 0 for j in range(N)] for i in range(N)]
        t=[row[:] for row in B]
        e=p
        while e:
            if e&1:
                res=[[sum(res[i][k]*t[k][j] for k in range(N))%p for j in range(N)] for i in range(N)]
            t=[[sum(t[i][k]*t[k][j] for k in range(N))%p for j in range(N)] for i in range(N)]
            e//=2
        for i in range(N):
            for j in range(N):
                total[i][j]=(total[i][j]+res[i][j])%p
    return total


def formula(N,p,A):
    K=sum(1 for i in range(N) for j in range(N) if A[i][j]==0)
    B0=[[A[i][j] if A[i][j]!=0 else 0 for j in range(N)] for i in range(N)]
    # compute B0^p mod p
    def matpow(B,exp):
        n=len(B)
        res=[[1 if i==j else 0 for j in range(n)] for i in range(n)]
        t=[row[:] for row in B]
        e=exp
        while e:
            if e&1:
                res=[[sum(res[i][k]*t[k][j] for k in range(n))%p for j in range(n)] for i in range(n)]
            t=[[sum(t[i][k]*t[k][j] for k in range(n))%p for j in range(n)] for i in range(n)]
            e//=2
        return res
    Bpow=matpow(B0,p)
    # compute deg_zero
    deg=[0]*N
    for i in range(N):
        for j in range(N):
            if A[i][j]==0:
                deg[i]+=1
    C=[[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if A[i][j]!=0:
                C[i][j]=(-A[i][j]*(deg[i]+deg[j]))%p
    pow1=pow(p-1,K,p)
    pow2=pow(p-1,K-1,p) if K>=1 else 0
    # matrix addition
    def add_mat(M1,M2,coeff2):
        n=N
        M=[[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                M[i][j]=(M1[i][j]+ coeff2*M2[i][j])%p
        return M
    S=add_mat(Bpow, C, pow2)
    S=[[S[i][j]*pow1%p for j in range(N)] for i in range(N)]
    return S

