        need=diff[s]
        vals=[strengths[i] for i in range(N) if teams[i]==s]
        dp=[INF]*(need+1)
        dp[0]=0
        for w in vals:
            for j in range(need, w-1, -1):
                if dp[j-w]+1<dp[j]:
                    dp[j]=dp[j-w]+1
        ans=dp[need]
