import sys

def main() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    teams = []  # 0-indexed
    strengths = []
    total = 0
    for _ in range(N):
        a = int(next(it)) - 1
        b = int(next(it))
        teams.append(a)
        strengths.append(b)
        total += b
    if total % 3 != 0:
        print(-1)
        return
    target = total // 3
    INF = 10 ** 9
    dp = [[INF] * (target + 1) for _ in range(target + 1)]
    dp[0][0] = 0
    for w, a in zip(strengths, teams):
        newdp = [[INF] * (target + 1) for _ in range(target + 1)]
        for s1 in range(target + 1):
            row = dp[s1]
            for s2 in range(target + 1):
                val = row[s2]
                if val == INF:
                    continue
                if s1 + w <= target:
                    nv = val + (1 if a != 0 else 0)
                    if nv < newdp[s1 + w][s2]:
                        newdp[s1 + w][s2] = nv
                if s2 + w <= target:
                    nv = val + (1 if a != 1 else 0)
                    if nv < newdp[s1][s2 + w]:
                        newdp[s1][s2 + w] = nv
                nv = val + (1 if a != 2 else 0)
                if nv < newdp[s1][s2]:
                    newdp[s1][s2] = nv
        dp = newdp
    ans = dp[target][target]
    print(ans if ans != INF else -1)

if __name__ == "__main__":
    main()

