def feasible(H, U, D, X):
    n=len(U)
    lo = max(0, H - D[0])  # lower bound for U'_1
    hi = min(U[0], H)
    if lo > hi:
        return False
    for i in range(1, n):
        new_lo = max(lo - X, max(0, H - D[i]))
        new_hi = min(hi + X, min(U[i], H))
        if new_lo > new_hi:
            return False
        lo, hi = new_lo, new_hi
    return True

