#!/usr/bin/env python3
import sys, bisect, collections

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it)); M = int(next(it)); Sx = int(next(it)); Sy = int(next(it))
    houses = [(int(next(it)), int(next(it))) for _ in range(N)]
    vert = collections.defaultdict(list)   # x -> list of (y1, y2)
    horiz = collections.defaultdict(list)  # y -> list of (x1, x2)
    cx, cy = Sx, Sy
    for _ in range(M):
        D = next(it); C = int(next(it))
        nx, ny = cx, cy
        if D == 'U':
            ny = cy + C
        elif D == 'D':
            ny = cy - C
        elif D == 'R':
            nx = cx + C
        elif D == 'L':
            nx = cx - C
        else:
            # illegal input - ignore
            pass
        if nx == cx:  # vertical move
            y1, y2 = cy, ny
            if y1 > y2:
                y1, y2 = y2, y1
            vert[cx].append((y1, y2))
        elif ny == cy:  # horizontal move
            x1, x2 = cx, nx
            if x1 > x2:
                x1, x2 = x2, x1
            horiz[cy].append((x1, x2))
        # update current position
        cx, cy = nx, ny

    finalX, finalY = cx, cy

    def merge_intervals(d: collections.defaultdict) -> dict:
        merged = {}
        for key, lst in d.items():
            lst.sort()
            cur_s, cur_e = lst[0]
            ms = []
            for s, e in lst[1:]:
                if s <= cur_e:  # overlap or touch
                    if e > cur_e:
                        cur_e = e
                else:
                    ms.append((cur_s, cur_e))
                    cur_s, cur_e = s, e
            ms.append((cur_s, cur_e))
            merged[key] = ms
        return merged

    merged_vert = merge_intervals(vert)
    merged_horiz = merge_intervals(horiz)

    count = 0
    for x, y in houses:
        found = False
        if x in merged_vert:
            arr = merged_vert[x]
            starts = [s for s, _ in arr]
            ends = [e for _, e in arr]
            i = bisect.bisect_right(starts, y) - 1
            if i >= 0 and y <= ends[i]:
                found = True
        if not found and y in merged_horiz:
            arr = merged_horiz[y]
            starts = [s for s, _ in arr]
            ends = [e for _, e in arr]
            j = bisect.bisect_right(starts, x) - 1
            if j >= 0 and x <= ends[j]:
                found = True
        if found:
            count += 1

    print(finalX, finalY, count)

if __name__ == "__main__":
    solve()

