"""
Solution for: lexicographically-smallest-generated-string
Problem ID: lcb_3770

Implement the function below.
"""

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        # Implementation
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        # Initialize string with 'a', and fixed flags
        s = ['a'] * L
        fixed = [False] * L
        # Apply 'T' constraints
        for i, ch in enumerate(str1):
            if ch == 'T':
                for p in range(m):
                    pos = i + p
                    if pos >= L:
                        return ""
                    required = str2[p]
                    if fixed[pos] and s[pos] != required:
                        return ""
                    s[pos] = required
                    fixed[pos] = True
        # Gather indices of 'F'
        F_indices = [i for i, ch in enumerate(str1) if ch == 'F']
        match_count = [0] * n
        matched_set = set()
        # Helper to update match_count for a specific i
        def compute_match(i):
            cnt = 0
            for p in range(m):
                if s[i + p] == str2[p]:
                    cnt += 1
            match_count[i] = cnt
            if cnt == m:
                matched_set.add(i)
            else:
                matched_set.discard(i)
        # Initial match count for all F indices
        for i in F_indices:
            compute_match(i)
        # Function to update after changing a position
        def update_position(pos, new_char):
            old_char = s[pos]
            if old_char == new_char:
                return
            # Positions covering this index
            start = max(0, pos - m + 1)
            end = min(n - 1, pos)
            for i in range(start, end + 1):
                if str1[i] != 'F':
                    continue
                offset = pos - i
                old_match = (old_char == str2[offset])
                new_match = (new_char == str2[offset])
                if old_match and not new_match:
                    match_count[i] -= 1
                elif not old_match and new_match:
                    match_count[i] += 1
                # Update matched set
                if match_count[i] == m:
                    matched_set.add(i)
                else:
                    matched_set.discard(i)
            s[pos] = new_char
        # Main loop
        while matched_set:
            # Pick any matched index; choose smallest for determinism
            i = min(matched_set)
            # Find rightmost candidate position not fixed within substring [i, i+m-1]
            cand_pos = -1
            for pos in range(i + m - 1, i - 1, -1):
                if not fixed[pos]:
                    cand_pos = pos
                    break
            if cand_pos == -1:
                return ""
            # Determine forbidden characters from all F substrings covering cand_pos
            forbidden = set()
            start = max(0, cand_pos - m + 1)
            end = min(n - 1, cand_pos)
            for j in range(start, end + 1):
                if str1[j] != 'F':
                    continue
                forbidden.add(str2[cand_pos - j])
            # Choose smallest letter not in forbidden
            for c in "abcdefghijklmnopqrstuvwxyz":
                if c not in forbidden:
                    new_char = c
                    break
            update_position(cand_pos, new_char)
        return "".join(s)

