def feasible(u,v,k,D):
    # choose a and b <= max(u,v)+D maybe
    M=max(u,v)+D+5
    for a in range(1,M+1):
        for b in range(1,M+1):
            if abs(a-b)>D: continue
            # generate sequence of length k unknowns alternating starting with a
            seq=[a]
            cur=a
            for i in range(k-1):
                cur=b if cur==a else a
                seq.append(cur)
            # also starting with b
            seq2=[b]
            cur=b
            for i in range(k-1):
                cur=a if cur==b else b
                seq2.append(cur)
            for start_seq in (seq,seq2):
                arr=[u]+start_seq+[v]
                if all(abs(arr[i]-arr[i+1])<=D for i in range(len(arr)-1)):
                    return True
    return False

