def shortest_pal_pref(S):
    T=S[::-1]
    n=len(S)
    m=len(T)
    # compute prefix function for pattern T
    pi=[0]*m
    for i in range(1,m):
        j=pi[i-1]
        while j>0 and T[i]!=T[j]:
            j=pi[j-1]
        if T[i]==T[j]:
            j+=1
        pi[i]=j
    # KMP matching S
    j=0
    for c in S:
        while j>0 and c!=T[j]:
            j=pi[j-1]
        if c==T[j]:
            j+=1
        if j==m:
            j=pi[j-1]
    matched=j
    # build answer
    suffix=S[:n-matched][::-1]
    ans=S+suffix
    return ans

