def sum_substrings(s):
    n=len(s)
    pref=[0]*(n+1)
    for i,ch in enumerate(s,1):
        pref[i]=pref[i-1]+(int(ch)*i)
    res=[]
    carry=0
    for pos in range(n):
        val=pref[n-pos]+carry
        res.append(val%10)
        carry=val//10
    while carry:
        res.append(carry%10)
        carry//=10
    return ''.join(map(str,res[::-1]))
