def count_connected_bipartite(n1,n2):
    edges = [(i,j) for i in range(n1) for j in range(n2)]
    cnt=0
    for mask in range(1<<len(edges)):
        # adjacency matrix
        row=[0]*n1
        col=[0]*n2
        for idx,(i,j) in enumerate(edges):
            if mask>>idx &1:
