def solve():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    A = [int(next(it)) - 1 for _ in range(N)]

    # Build directed graph `i -> A[i]`
    G = [[] for _ in range(N)]
    for i in range(N):
        G[i].append(A[i])

    sys.setrecursionlimit(10000)
    # Tarjan's SCC
    index = 0
    indices = [-1] * N
    low = [0] * N
    stack = []
    onstack = [False] * N
    comp = [-1] * N
    comp_cnt = 0

    def dfs(v):
        nonlocal index, comp_cnt
        indices[v] = low[v] = index
        index += 1
        stack.append(v)
        onstack[v] = True
        for w in G[v]:
            if indices[w] == -1:
                dfs(w)
                low[v] = min(low[v], low[w])
            elif onstack[w]:
                low[v] = min(low[v], indices[w])
        if low[v] == indices[v]:
            while True:
                w = stack.pop()
                onstack[w] = False
                comp[w] = comp_cnt
