import random

def lcs_len(S,T):
    # standard dp
    n=len(S);m=len(T)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1,-1,-1):
        for j in range(m-1,-1,-1):
            if S[i]==T[j]:
                dp[i][j]=dp[i+1][j+1]+1
            else:
                dp[i][j]=max(dp[i+1][j],dp[i][j+1])
    return dp[0][0]

def greedy_len(S,T):
    ptr=0;cnt=0
    for c in T:
        try:
            idx=S.index(c,ptr)
            cnt+=1
            ptr=idx+1
        except ValueError:
            pass
    return cnt

