#!/usr/bin/env python3
import sys, math

def can_color_all(N: int, K: int) -> bool:
    # Special case N==2: always possible.
    if N == 2:
        return True
    # If N is divisible by 4, impossible for any K.
    if N % 4 == 0:
        return False
    # N is even but not divisible by 4 (i.e. N % 4 == 2)
    if N % 2 == 0:
        # All K except the opposite point (K == N/2) are possible.
        return K != N // 2
    # N is odd.
    # Possible iff K and N are coprime.
    return math.gcd(N, K) == 1


def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
