def min_cost_bruteforce(P):
    n=len(P)
    start=tuple(P)
    target=tuple(sorted(P))
    pq=[(0,start)]
    seen={start:0}
    while pq:
        cost,state=heapq.heappop(pq)
        if state==target:
            return cost
        if seen[state]!=cost: continue
        for i in range(n-1):
            nxt=list(state)
            nxt[i],nxt[i+1]=nxt[i+1],nxt[i]
            nxt=tuple(nxt)
            nc=cost+i+1
