def fenwick_solution(N,P):
    size=N
    tree=[0]*(size+1)
    def add(i,delta):
        while i<=size:
            tree[i]+=delta
            i+=i&-i
    for i in range(1,size+1):
        add(i,1)
    def find_kth(k):
        idx=0
        bit=1<<(size.bit_length()-1)
        while bit:
            nxt=idx+bit
            if nxt<=size and tree[nxt]<k:
                k-=tree[nxt]
                idx=nxt
            bit>>=1
        return idx+1
    ans=[0]*size
    for i in range(N-1,-1,-1):
        pos=find_kth(P[i])-1
        ans[pos]=i+1
        add(pos+1,-1)
    return ans
