def compute_E(A):
    N=len(A)
    last=[0]*(N+1)
    cur_min=[0]*(N)
    prev=[0]*(N)
    ans=[0]*(N)
    for idx,x in enumerate(A, start=1):
        last[x]=idx
        for u in (x-1, x):
            if 1<=u<=N-1:
                length_old= (idx-1)-prev[u]
                ans[u]+= cur_min[u]*length_old
                new_min = min(last[u], last[u+1])
                cur_min[u]=new_min
                prev[u]=idx-1
    for u in range(1,N):
        ans[u]+= cur_min[u]*(N-prev[u])
    return sum(ans[1:])

