import sys

def sub_without_occurrences(N, positions):
    # positions sorted ascending 1-indexed
    gaps = []
    prev = 0
    for p in positions:
        gaps.append(p - prev - 1)
        prev = p
    gaps.append(N - prev)
    total = 0
    for g in gaps:
        if g:
            total += g * (g + 1) // 2
    return total


def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    positions = [[] for _ in range(N+1)]
    for idx, val in enumerate(A, start=1):
        positions[val].append(idx)
    total_sub = N * (N + 1) // 2
    sum_d = 0
    for v in range(1, N+1):
        if not positions[v]:
            continue
        sub_without = sub_without_occurrences(N, positions[v])
        sum_d += total_sub - sub_without
    sum_c = 0
    for v in range(1, N):
        pos_a = positions[v]
        pos_b = positions[v+1]
        if not pos_a or not pos_b:
            continue
        subA = sub_without_occurrences(N, pos_a)
        subB = sub_without_occurrences(N, pos_b)
        # merge for union positions of v and v+1
        merged = []
        i, j = 0, 0
        while i < len(pos_a) and j < len(pos_b):
            if pos_a[i] < pos_b[j]:
                merged.append(pos_a[i]); i += 1
            elif pos_a[i] > pos_b[j]:
                merged.append(pos_b[j]); j += 1
            else:
                merged.append(pos_a[i]); i += 1; j += 1
        if i < len(pos_a):
            merged.extend(pos_a[i:])
        if j < len(pos_b):
            merged.extend(pos_b[j:])
        subBoth = sub_without_occurrences(N, merged)
        sum_c += total_sub - subA - subB + subBoth
    ans = sum_d - sum_c
    print(ans)

if __name__ == "__main__":
    solve()

