#!/usr/bin/env python3
import sys, math

def find_pair(N: int):
    # iterate over possible d = x - y
    a_max = int(N ** (1/3)) + 3
    for d in range(1, a_max + 1):
        if N % d != 0:
            continue
        b = N // d  # b = 3y^2 + 3dy + d^2
        # we derived D = 12b - 3d^2
        D = 12 * b - 3 * d * d
        if D <= 0:
            continue
        s = math.isqrt(D)
        if s * s != D:
            continue
        if (s - 3 * d) % 6 != 0:
            continue
        y = (s - 3 * d) // 6
        if y <= 0:
