import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    X = int(next(it))
    items_by_type = {1: [], 2: [], 3: []}
    totals = {1: 0, 2: 0, 3: 0}
    for _ in range(N):
        v = int(next(it))
        a = int(next(it))
        c = int(next(it))
        items_by_type[v].append((c, a))
        totals[v] += a
    # DP for each vitamin type
    dp_type = {}
    for t in (1, 2, 3):
        dp = [0] * (X + 1)
        for c, a in items_by_type[t]:
            for cap in range(X, c - 1, -1):
                val = dp[cap - c] + a
                if val > dp[cap]:
                    dp[cap] = val
        dp_type[t] = dp
    max_possible = min(totals[1], totals[2], totals[3])

    def feasible(M):
        if M == 0:
            return True
        total_cal = 0
        for t in (1, 2, 3):
            dp = dp_type[t]
            cal_needed = None
            for cap in range(X + 1):
                if dp[cap] >= M:
                    cal_needed = cap
                    break
            if cal_needed is None:
                return False
            total_cal += cal_needed
            if total_cal > X:
                return False
        return True

    low, high = 0, max_possible
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1
    print(low)

if __name__ == "__main__":
    solve()

