import sys

def kth_value(N,K,A,B,C):
    A=sorted(A,reverse=True)
    B=sorted(B,reverse=True)
    C=sorted(C,reverse=True)
    import heapq
    heap=[(- (A[0]*B[0]+B[0]*C[0]+C[0]*A[0]),0,0,0)]
    visited={(0,0,0)}
    ans=None
    for _ in range(K):
        val,i,j,k=heapq.heappop(heap)
        ans=-val
        if i+1<N:
            key=(i+1,j,k)
            if key not in visited:
                visited.add(key)
                heapq.heappush(heap,(-(A[i+1]*B[j]+B[j]*C[k]+C[k]*A[i+1]),i+1,j,k))
        if j+1<N:
            key=(i,j+1,k)
            if key not in visited:
                visited.add(key)
                heapq.heappush(heap,(-(A[i]*B[j+1]+B[j+1]*C[k]+C[k]*A[i]),i,j+1,k))
        if k+1<N:
            key=(i,j,k+1)
            if key not in visited:
                visited.add(key)
                heapq.heappush(heap,(-(A[i]*B[j]+B[j]*C[k+1]+C[k+1]*A[i]),i,j,k+1))
    return ans

