#!/usr/bin/env python3
import sys
from functools import lru_cache

def beautiful_count(l: int, r: int) -> int:
    """Return number of positive integers in [l,r] such that the product of its digits
    is divisible by the sum of its digits.
    """
    def count_upto(x: int) -> int:
        if x <= 0:
            return 0
        digits = list(map(int, str(x)))
        n = len(digits)
        total = 0
        # Max sum of digits for numbers <= 10^9 is 9*10 = 90, but 81 is safe
        for S in range(1, 82):
            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool, started: bool, sum_: int, prod_mod: int) -> int:
                if sum_ > S:
                    return 0
                if pos == n:
                    return 1 if started and sum_ == S and prod_mod % S == 0 else 0
                limit = digits[pos] if tight else 9
                tot = 0
                for d in range(0, limit + 1):
                    ntight = tight and d == limit
                    if not started:
                        if d == 0:
                            # still not started, product doesn't matter
                            tot += dfs(pos + 1, ntight, False, 0, prod_mod)
                        else:
                            tot += dfs(pos + 1, ntight, True, d, d % S)
                    else:
                        if d == 0:
                            # skip numbers with zero after start
                            continue
                        new_prod = (prod_mod * d) % S
                        tot += dfs(pos + 1, ntight, True, sum_ + d, new_prod)
                return tot
            total += dfs(0, True, False, 0, 1)
        return total

    return count_upto(r) - count_upto(l - 1)


def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    l, r = map(int, data[:2])
    print(beautiful_count(l, r))

if __name__ == "__main__":
    solve()

