def solve(N, A):
    roots=[i for i,a in enumerate(A,1) if a==0]
    for i in range(len(roots)-1):
        A[roots[i]-1]=roots[i+1]
    # Build adjacency
    children=[[] for _ in range(N+1)]
    root=None
    for i,a in enumerate(A,1):
        if a==0:
            root=i
        else:
            children[a].append(i)
    # DFS stack post-order
    sz=[0]*(N+1)
    stack=[(root,0)]
    order=[]
    while stack:
        node,idx=stack.pop()
        if idx==0:
            stack.append((node,1))
            for child in children[node]:
                stack.append((child,0))
        else:
            s=1
            for child in children[node]:
                s+=sz[child]
            sz[node]=s
    fact=[1]*(N+1)
    for i in range(1,N+1):
        fact[i]=fact[i-1]*i%MOD
    inv=[1]*(N+1)
    inv[1]=1
    for i in range(2,N+1):
        inv[i]=MOD - MOD//i * inv[MOD%i]%MOD
    res=fact[N]
    for i in range(1,N+1):
        res=res*inv[sz[i]]%MOD
    return res

