def min_cost_for_s(S, P, Pmax, M):
    if S == 0:
        return 0
    low = 0
    high = Pmax * (2 * S - 1)
    while low < high:
        mid = (low + high) // 2
        cnt = 0
        for pi in P:
            cnt += (mid // pi + 1) // 2
        if cnt >= S:
            high = mid
        else:
            low = mid + 1
    T = low
    total_cnt = 0
    total_sum = 0
    for pi in P:
        m = (T // pi + 1) // 2
        total_cnt += m
        total_sum += pi * m * m
    g = total_cnt - S
    return total_sum - g * T

