import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    Rs = set()
    Cs = set()
    Ds1 = set()
    Ds2 = set()
    for _ in range(M):
        a = int(next(it)); b = int(next(it))
        Rs.add(a)
        Cs.add(b)
        Ds1.add(a+b)
        Ds2.add(a-b)
    r = len(Rs); c = len(Cs)
    d1 = len(Ds1); d2 = len(Ds2)
    # total cells
    total = N * N
    # Count cells attacked by each line type (inclusion-exclusion)
    # Single line counts
    sum_single = r * N + c * N
    # diagonals
    # for sum diagonal d, length depends on value
    len_sum_diag = 0
    for d in Ds1:
        if d <= N+1:
            len_sum_diag += d-1
        else:
            len_sum_diag += 2*N - d + 1
    len_diff_diag = 0
    for d in Ds2:
        len_diff_diag += N - abs(d)
    sum_single += len_sum_diag + len_diff_diag
    # Prepare sorted lists for range queries
    sorted_d1 = sorted(Ds1)
    sorted_d2 = sorted(Ds2)
    import bisect
    def count_in_range(sorted_list, low, high):
        return bisect.bisect_right(sorted_list, high) - bisect.bisect_left(sorted_list, low)
    # pair intersections
    AB = r * c
    AC = 0
    for i in Rs:
        AC += count_in_range(sorted_d1, i+1, i+N)
    AD = 0
    for i in Rs:
        AD += count_in_range(sorted_d2, i-N, i-1)
    BC = 0
    for j in Cs:
        BC += count_in_range(sorted_d1, j+1, j+N)
    BD = 0
    for j in Cs:
        BD += count_in_range(sorted_d2, 1-j, N-j)
    # CD intersection (diff and sum diagonals)
    CD = 0
    for sum_d in Ds1:
        # for given sum_d, we need diff_d = sum_d - 2i where i in [1,N] integer
        # Equivalent to iterate over diff_d in Ds2 that satisfies parity and bounds.
        # We'll iterate over Ds2 directly as constraints small.
        for diff_d in Ds2:
            if (sum_d + diff_d) & 1:
                continue
            i = (sum_d + diff_d) // 2
            j = (sum_d - diff_d) // 2
            if 1 <= i <= N and 1 <= j <= N:
                CD += 1
    sum_pair = AB + AC + AD + BC + BD + CD
    # triple intersections
    ABC = 0
    for i in Rs:
        for j in Cs:
            if i + j in Ds1:
                ABC += 1
    ABD = 0
    for i in Rs:
        for j in Cs:
            if i - j in Ds2:
                ABD += 1
    ACD = 0
    for i in Rs:
        for diff_d in Ds2:
            j = i - diff_d
            if 1 <= j <= N:
                s = i + j
                if s in Ds1:
                    ACD += 1
    BCD = 0
    for j in Cs:
        for diff_d in Ds2:
            i = j + diff_d
            if 1 <= i <= N:
                s = i + j
                if s in Ds1:
                    BCD += 1
    ABCD = 0
    for i in Rs:
        for j in Cs:
            s = i + j
            d = i - j
            if s in Ds1 and d in Ds2:
                ABCD += 1
    sum_triple = ABC + ABD + ACD + BCD
    # quadruple intersection
    quad = ABCD
    attacked = sum_single - sum_pair + sum_triple - quad
    free = total - attacked
    print(free)

if __name__ == "__main__":
    solve()

