#!/usr/bin/env python3
import sys

class DSU:
    def __init__(self, n):
        self.parent=list(range(n))
        self.rank=[0]*n
    def find(self, x):
        while self.parent[x]!=x:
            self.parent[x]=self.parent[self.parent[x]]
            x=self.parent[x]
        return x
    def union(self, a,b):
        a=self.find(a); b=self.find(b)
        if a==b: return False
        if self.rank[a]<self.rank[b]:
            a,b=b,a
        self.parent[b]=a
        if self.rank[a]==self.rank[b]:
            self.rank[a]+=1
        return True

def solve():
    input=sys.stdin.readline
    H,W=map(int,input().split())
    F=[list(map(int,input().split())) for _ in range(H)]
    Q=int(input().strip())
    queries=[]
    for _ in range(Q):
        a,b,y,c,d,z=map(int,input().split())
        # convert to 0-index
        u=(a-1)*W+(b-1)
        v=(c-1)*W+(d-1)
        queries.append((u,v,y,z))
    N=H*W
    node_height=[0]*N
    for i in range(H):
        for j in range(W):
            node_height[i*W+j]=F[i][j]
    # sort node indices by height descending
    order=sorted(range(N), key=lambda x: node_height[x], reverse=True)
    active=[False]*N
    dsu=DSU(N)
    # queries_of list per node index
    qof=[[] for _ in range(N)]
    for idx,(u,v,y,z) in enumerate(queries):
        qof[u].append(idx)
        qof[v].append(idx)
    answer=[-1]*Q
    # directions
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    for id in order:
        active[id]=True
        x=id//W; y=id%W
        # union with active neighbors
        for dx,dy in dirs:
            nx=x+dx; ny=y+dy
            if 0<=nx<H and 0<=ny<W:
                nid=nx*W+ny
                if active[nid]:
                    dsu.union(id,nid)
        # check queries involving this node
        for qi in qof[id]:
            if answer[qi]!=-1: continue
            u,v,_,_ = queries[qi]
            other = v if u==id else u
            if not active[other]:
                continue
            if dsu.find(id)==dsu.find(other):
                answer[qi]=node_height[id]
    out_lines=[]
    for idx,(u,v,y,z) in enumerate(queries):
        M=answer[idx]
        if M>=max(y,z):
            cost=abs(y-z)
        else:
            cost=(y-M)+(z-M)
        out_lines.append(str(cost))
    sys.stdout.write("\n".join(out_lines))

if __name__=="__main__":
    solve()

