"""

import sys
sys.setrecursionlimit(1_000_000)

def can_decompose(nk, k, edges):
    if k == 1:
        return True
    g = [[] for _ in range(nk + 1)]
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    visited = [False] * (nk + 1)

    def dfs(u):
        visited[u] = True
        children = [v for v in g[u] if not visited[v]]
        if not children:
            return 1
        closecnt = 0
        pending = []
        for v in children:
            r = dfs(v)
            if r == -1:
                return -1
            if r == 0:
                continue
            len_r = r + 1
            if len_r == k:
                closecnt += 1
                if closecnt > 1:
                    return -1
            else:
                pending.append(len_r)
        if closecnt == 1:
            if pending:
                return -1
            return 0
        if not pending:
            return 0
        if len(pending) == 1:
            return pending[0]
        if len(pending) == 2:
            a, b = pending
            if a + b + 1 == k:
                return 0
            else:
                return -1
        return -1

    res = dfs(1)
    return res == 0

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(map(int, data))
    N = next(it)
    K = next(it)
    nk = N * K
    edges = [(next(it), next(it)) for _ in range(nk - 1)]
    ok = can_decompose(nk, K, edges)
    print("Yes" if ok else "No")

if __name__ == "__main__":
    solve()

