#!/usr/bin/env python3
import sys

def solve():
    data=sys.stdin.read().strip().split()
    if not data:
        return
    it=iter(data)
    n=int(next(it))
    adj=[[] for _ in range(n+1)]
    for _ in range(n-1):
        u=int(next(it)); v=int(next(it))
        adj[u].append(v); adj[v].append(u)
    deg=[len(adj[i]) for i in range(n+1)]
    max_keep=0
    for c in range(1,n+1):
        # prepare list of available leaf counts for neighbors of c
        # for each neighbor b of c, number of other neighbors available as leaves: deg(b)-1
        counts=[deg[b]-1 for b in adj[c] if deg[b]-1>0]
        if not counts:
            continue
        counts.sort(reverse=True)
        for idx,val in enumerate(counts):
            size=1+(idx+1)*(1+val)  # 1 center + (idx+1) branch roots + each with val leaves
            if size>max_keep:
                max_keep=size
    # Problem guarantees at least one snowflake possible
    if max_keep==0:
        max_keep=1
    ans=n-max_keep
    print(ans)

if __name__=='__main__':
    solve()

