def min_moves_dp(need):
    n=len(need)
    L=-1
    for i in range(n-1,-1,-1):
        if need[i]>0:
            L=i
            break
    if L==-1:
        return 0
    prev=0
    for i in range(0,L+1):
        if i==0:
            dp=1 + 2*max(0, need[0]-1)
        else:
            dp=prev + 1 + 2*max(0, need[i]-1)
        prev=dp
    return prev

