            cur = i
            while not visited[cur]:
                visited[cur] = True
                cycle.append(cur)
                cur = P[cur]
            L = len(cycle)
            shift = pow(2, K, L) if L else 0
            for j, idx in enumerate(cycle):
                res[idx] = cycle[(j + shift) % L]
    print(' '.join(str(res[i]) for i in range(1, N+1)))

