    neighbors = [[] for _ in range(H * W)]
    for i in range(H):
        line = grid[i]
        for j in range(W):
            if line[j] == '.':
                cur = idx(i, j)
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
