def minOperations(self, queries: List[List[int]]) -> int:
    # Precompute powers of 4 up to > 1e9
    max_val = 10**9
    pow4 = [1]
    while pow4[-1] <= max_val:
        pow4.append(pow4[-1] * 4)
    total_sum = 0
    for l, r in queries:
        n = r - l + 1
        sum_g1 = 0
        k = 0
        # iterate powers
        while pow4[k] <= r:
            start = max(l, pow4[k])
            end = min(r, pow4[k+1]-1 if k+1 < len(pow4) else r)
            if start <= end:
                sum_g1 += (end - start + 1) * (k + 1)
            k += 1
        total_sum += (sum_g1 + 1) // 2
    return total_sum

