import sys
from collections import defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    X = int(next(it))
    A = [int(next(it)) for _ in range(N)]

    freq = [0] * (X + 1)
    idx_of = defaultdict(list)
    for pos, v in enumerate(A, start=1):
        freq[v] += 1
        idx_of[v].append(pos)
    values = [v for v in range(1, X+1) if freq[v] > 0]
    found = False
    ans_vals = None
    for i, p in enumerate(values):
        fp = freq[p]
        # we only need to iterate q >= p
        for j in range(i, len(values)):
            q = values[j]
            if p + q > X:
                break
            r = X - p - q
            if r < 1 or r > X or freq[r] == 0:
                continue
            fr = freq[r]
            if p == q == r:
                if fr >= 3:
                    found = True
            elif p == q:
                if fp >= 2 and fr >= 1:
                    found = True
            elif q == r:
                if fq := freq[q]; fq >= 2 and fp >= 1:
                    found = True
            elif p == r:
                if fr >= 2 and fq >= 1:
                    found = True
            else:
                found = True
            if found:
                ans_vals = (p, q, r)
                break
        if found:
            break
    if not found:
        print(-1)
        return
    p, q, r = ans_vals
    i1 = idx_of[p].pop()
    i2 = idx_of[q].pop()
    i3 = idx_of[r].pop()
    res = sorted([i1, i2, i3])
    print(*res)

if __name__ == "__main__":
    solve()

