from collections import deque

def min_moves(N,edges,S,T):
    graph=[set() for _ in range(N)]
    for u,v in edges:
        graph[u].add(v)
        graph[v].add(u)
    start=(S,T)
    target=(T,S)
    if start==target:
        return 0
    seen={start}
    q=deque([(S,T,0)])
    while q:
        a,b,d=q.popleft()
        for move in [(a,nb) for nb in graph[a]] + [(nb,b) for nb in graph[b]]:
            na,nb=move
            if na==nb: continue
            if (na,nb) not in seen:
                if (na,nb)==(T,S):
                    return d+1
                seen.add((na,nb))
                q.append((na,nb,d+1))
    return None

