    for _ in range(M):
        a=int(next(it)); b=int(next(it)); c=int(next(it))
        h_a=a-1
        c_a=a-1+N
        h_b=b-1
        var_set={h_a,c_a,h_b}
        const=c
        # Gaussian elimination over GF(2)
        while var_set:
            v=next(iter(var_set))
            if v not in pivot:
                equations.append((v, frozenset(var_set), const))
                pivot[v]=len(equations)-1
                break
            else:
                idx=pivot[v]
                pv, pv_set, pv_const=equations[idx]
