def min_ops(seq):
    from collections import deque
    start = tuple(seq)
    seen={start:0}
    q=deque([start])
    while q:
        cur=q.popleft()
        d=seen[cur]
        if not cur:
            return d
        k=len(cur)
        # op1: swap adjacent
        for i in range(k-1):
