import sys
from math import gcd
MOD=10**9+7

def count_seq_pairs(nums):
    # dp state: (g1,g2,f1,f2) -> count
    dp={(0,0,0,0):1}
    for x in nums:
        ndp={}
        for (g1,g2,f1,f2),cnt in dp.items():
            # skip element
            ndp[(g1,g2,f1,f2)]=(ndp.get((g1,g2,f1,f2),0)+cnt)%MOD
            # assign to seq1
            new_g1 = x if f1==0 else gcd(g1,x)
            ndp[(new_g1,g2,1,f2)] = (ndp.get((new_g1,g2,1,f2),0)+cnt)%MOD
            # assign to seq2
            new_g2 = x if f2==0 else gcd(g2,x)
            ndp[(g1,new_g2,f1,1)] = (ndp.get((g1,new_g2,f1,1),0)+cnt)%MOD
        dp=ndp
    ans=0
    for (g1,g2,f1,f2),cnt in dp.items():
        if f1==1 and f2==1 and g1==g2:
            ans=(ans+cnt)%MOD
    return ans

def main():
    import json, sys
    data=sys.stdin.read().strip()
    if not data:
        return
    nums=json.loads(data)
    print(count_seq_pairs(nums))

if __name__=='__main__':
    main()

