import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    # Find positions where adjacent elements are equal
    eq_positions = [i for i in range(N-1) if A[i] == A[i+1]]
    best = 0
    idx = 0
    while idx < len(eq_positions):
        # Build a run of consecutive pair positions spaced by 2
        run = [eq_positions[idx]]
        while idx + 1 < len(eq_positions) and eq_positions[idx+1] == eq_positions[idx] + 2:
            idx += 1
            run.append(eq_positions[idx])
        # Sliding window over run with distinct pair values
        seen = {}
        l = 0
        for r, pos in enumerate(run):
            val = A[pos]
            if val in seen:
                # Move left pointer to one after previous occurrence
                while l <= seen[val]:
                    l += 1
                seen[val] = r
            else:
                seen[val] = r
            cur_len = (r - l + 1) * 2
            if cur_len > best:
                best = cur_len
        idx += 1
    print(best)

if __name__ == "__main__":
    solve()

