"""
Solution for: count-the-number-of-winning-sequences
Problem ID: lcb_3588

Implement the function below.
"""

MOD=10**9+7

# Map creature to id
A_MAP={'F':0,'W':1,'E':2}

# Precompute score delta: delta[bob][alice] = +1 if Bob wins, -1 if Alice wins, 0 tie
# Conditions: Bob wins if (Bob, Alice) in win_prec
win_prec = {(0,2),(1,0),(2,1)}

delta=[[0]*3 for _ in range(3)]
for b in range(3):
    for a in range(3):
        if (b,a) in win_prec:
            delta[b][a]=1
        elif (a,b) in win_prec:
            delta[b][a]=-1
        else:
            delta[b][a]=0

class Solution:
    def countWinningSequences(self,s: str) -> int:
        n=len(s)
        a=[A_MAP[ch] for ch in s]
        offset=n
        size=2*n+1
        # dp[prev_move][diff+offset]
        dp=[[0]*size for _ in range(3)]
        # first round
        for b in range(3):
            d=delta[b][a[0]]
            dp[b][offset+d]=1
        # iterate
        for i in range(1,n):
            new=[[0]*size for _ in range(3)]
            for prev in range(3):
                arr=dp[prev]
                for diff_idx,cnt in enumerate(arr):
                    if cnt==0:
                        continue
                    for nxt in range(3):
                        if nxt==prev:
                            continue
                        nd=delta[nxt][a[i]]
                        new_idx=diff_idx+nd
                        new[nxt][new_idx]=(new[nxt][new_idx]+cnt)%MOD
            dp=new
        # sum all sequences where Bob score > Alice score (diff>0)
        ans=0
        for b in range(3):
            for idx,cnt in enumerate(dp[b]):
                if cnt==0:
                    continue
                if idx-offset>0:
                    ans=(ans+cnt)%MOD
        return ans

if __name__ == "__main__":
    # quick sanity tests
    sol=Solution()
    print(sol.countWinningSequences("FFF"))  # expected 3
    print(sol.countWinningSequences("FWEFW"))  # expected 18

