"""
Solution for counting number of arrays with exactly k equal adjacent pairs.
"""

MOD = 10 ** 9 + 7

# Precompute factorials up to MAX_N
MAX_N = 10 ** 5 + 5

def modinv(x):
    return pow(x, MOD - 2, MOD)

fac = [1] * (MAX_N)
invfac = [1] * (MAX_N)
for i in range(1, MAX_N):
    fac[i] = fac[i-1] * i % MOD
invfac[MAX_N-1] = modinv(fac[MAX_N-1])
for i in range(MAX_N-2, -1, -1):
    invfac[i] = invfac[i+1] * (i+1) % MOD

def comb(n, k):
    if k < 0 or k > n:
        return 0
    return fac[n] * invfac[k] % MOD * invfac[n-k] % MOD


def count_good_arrays(n, m, k):
    r = n - k  # number of runs
    if r < 1 or r > n:
        return 0
    if m == 1:
        return m if r == 1 else 0
    if r == 1:
        # All elements equal, m choices
        return m % MOD
    # General case
    res = m * pow(m-1, r-1, MOD) % MOD
    res = res * comb(n-1, r-1) % MOD
