import itertools, random

MOD=998244353

def expected(order, a):
    pos={}
    for idx, v in enumerate(order, start=1):
        pos[v]=idx
    return sum(a[v-1]*pos[v] for v in range(1,len(a)+1))

def all_orders(N, children):
    # generate all topological orders respecting parent before child
    # for small N (<8)
    results=[]
    def dfs(available, current):
        if len(current)==N:
            results.append(current[:])
            return
        for v in list(available):
            a=current+[v]
            new_av=set(available)
            new_av.remove(v)
            for c in children[v]:
                # child parent is v by construction
                # parent already in current
                new_av.add(c)
            dfs(new_av, a)
    # initial available children[0]
    avail=set(children[0])
    dfs(avail, [])
    return results


def brute(N,p,a):
    children=[[] for _ in range(N+1)]
    for i in range(1,N+1):
        children[p[i-1]].append(i)
    orders=all_orders(N, children)
    best=None
    best_o=None
    for order in orders:
        val=expected(order,a)
        if best is None or val<best:
            best=val; best_o=order
    return best,best_o

